package com.prem.order; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.web.server.ServerHttpSecurity; import org.springframework.security.web.server.SecurityWebFilterChain; @Configuration @EnableMethodSecurity public class SecurityConfig { @Bean SecurityWebFilterChain security(ServerHttpSecurity http){return http.csrf(ServerHttpSecurity.CsrfSpec::disable).authorizeExchange(e->e.pathMatchers("/actuator/health").permitAll().pathMatchers("/admin/**").hasRole("ADMIN").pathMatchers("/orders/**").hasAnyRole("USER","ADMIN").anyExchange().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(new KeycloakRoleConverter()))).build();} }
